from datetime import date
import pytest


# --- Normal valid cases: start before end ---

def test_start_before_end_same_year():
    assert valid_date_range("2023-01-01", "2023-12-31") is True


def test_start_before_end_different_years():
    assert valid_date_range("2020-06-15", "2023-06-15") is True


def test_start_before_end_by_one_day():
    assert valid_date_range("2023-05-10", "2023-05-11") is True


def test_start_before_end_by_one_month():
    assert valid_date_range("2023-05-10", "2023-06-10") is True


# --- Boundary: start equals end ---

def test_start_equals_end():
    assert valid_date_range("2023-01-01", "2023-01-01") is True


def test_start_equals_end_leap_day():
    assert valid_date_range("2020-02-29", "2020-02-29") is True


# --- Cases where start is after end (should be False) ---

def test_start_after_end_same_year():
    assert valid_date_range("2023-12-31", "2023-01-01") is False


def test_start_after_end_by_one_day():
    assert valid_date_range("2023-05-11", "2023-05-10") is False


def test_start_after_end_different_years():
    assert valid_date_range("2023-06-15", "2020-06-15") is False


# --- Return type checks ---

def test_returns_bool_true():
    result = valid_date_range("2023-01-01", "2023-01-02")
    assert result is True
    assert isinstance(result, bool)


def test_returns_bool_false():
    result = valid_date_range("2023-01-02", "2023-01-01")
    assert result is False
    assert isinstance(result, bool)


# --- Invalid ISO format strings (ValueError branch -> False) ---

def test_invalid_start_format_slashes():
    assert valid_date_range("2023/01/01", "2023-01-02") is False


def test_invalid_end_format_slashes():
    assert valid_date_range("2023-01-01", "2023/01/02") is False


def test_invalid_start_not_a_date():
    assert valid_date_range("not-a-date", "2023-01-02") is False


def test_invalid_end_not_a_date():
    assert valid_date_range("2023-01-01", "hello") is False


def test_empty_start_string():
    assert valid_date_range("", "2023-01-02") is False


def test_empty_end_string():
    assert valid_date_range("2023-01-01", "") is False


def test_both_empty_strings():
    assert valid_date_range("", "") is False


def test_invalid_month():
    assert valid_date_range("2023-13-01", "2023-12-31") is False


def test_invalid_day():
    assert valid_date_range("2023-01-32", "2023-12-31") is False


def test_invalid_leap_day_non_leap_year():
    # 2021 is not a leap year, so Feb 29 is invalid
    assert valid_date_range("2021-02-29", "2021-12-31") is False


def test_partial_date_year_only():
    assert valid_date_range("2023", "2023-01-01") is False


def test_partial_date_year_month():
    assert valid_date_range("2023-01", "2023-01-01") is False


def test_whitespace_padded_date():
