# --- Invalid types (TypeError branch -> False) ---

def test_none_start():
    assert valid_date_range(None, "2023-01-02") is False


def test_none_end():
    assert valid_date_range("2023-01-01", None) is False


def test_both_none():
    assert valid_date_range(None, None) is False


