def test_no_exception_for_garbage_inputs():
    # These should all quietly return False rather than raise
    for bad in [None, 123, [], {}, "garbage", "2023-99-99"]:
        assert valid_date_range(bad, "2023-01-01") is False
        assert valid_date_range("2023-01-01", bad) is False

